// Retro reaction sounds of Crazy Tuk (0.19.1, the owner's decision: simple console-style effects like sfxr / jsfxr), generated by code
// into assets/audio-src/retro/*.wav (mono 44.1 kHz, 16 bit, peak −1 dB). No downloads, no licences: the game's own sounds (CC0).
// From there tools/build-sounds.mjs puts them into the slots (assets/audio-src/sounds.json, source "retro").
//   node tools/make-retro-sounds.mjs            (rewrites every file; deterministic: a seeded noise generator)
// Sounds: coin (exact gate), beep-good / beep-ok (the other gates), combo (rising tru-lu-lu), nitro (whoosh up), boom-light / -medium / -heavy
// (hits), crunch-c / -b / -t / -u ×2 (smashed cone / bin / table / umbrella), whistle (near miss).
import { writeFile, mkdir } from 'node:fs/promises';

const SR = 44100, OUT = 'assets/audio-src/retro';
let seed = 12345;
const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
const noise = () => rnd() * 2 - 1;

// ---- building blocks: every generator returns Float32Array samples
const secs = (s) => Math.round(s * SR);
const env = (i, n, a, d) => { const t = i / SR; return t < a ? t / a : Math.max(0, 1 - (t - a) / Math.max(1e-4, d)); };   // attack then linear decay to the end
const square = (ph, duty = 0.5) => ((ph % 1) < duty ? 1 : -1);
const saw = (ph) => ((ph % 1) * 2 - 1);
const tri = (ph) => 1 - 4 * Math.abs(((ph + 0.25) % 1) - 0.5);
// a tone with a pitch curve f(t) in Hz; wave: square | saw | tri | sine
function tone(len, f, { wave = 'square', duty = 0.5, amp = 1, attack = 0.004, decay = len, vib = 0 } = {}) {
  const n = secs(len), out = new Float32Array(n); let ph = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR, hz = f(t) * (1 + vib * Math.sin(2 * Math.PI * 7 * t));
    ph += hz / SR;
    const w = wave === 'square' ? square(ph, duty) : wave === 'saw' ? saw(ph) : wave === 'tri' ? tri(ph) : Math.sin(2 * Math.PI * ph);
    out[i] = w * amp * env(i, n, attack, decay);
  }
  return out;
}
// filtered noise burst: one-pole low-pass cutoff curve c(t) in Hz, optional one-pole high-pass
function burst(len, { lp = () => 4000, hp = 0, amp = 1, attack = 0.002, decay = len, crush = 1 } = {}) {
  const n = secs(len), out = new Float32Array(n); let y = 0, hy = 0, hx = 0, held = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR, k = 1 - Math.exp(-2 * Math.PI * lp(t) / SR);
    if (crush <= 1 || i % crush === 0) held = noise();   // crush: hold each value for N samples (the gritty old-console grain)
    y += k * (held - y);
    let v = y;
    if (hp) { const a = Math.exp(-2 * Math.PI * hp / SR); hy = a * (hy + v - hx); hx = v; v = hy; }
    out[i] = v * amp * env(i, n, attack, decay);
  }
  return out;
}
const mix = (...parts) => { const n = Math.max(...parts.map((p) => p.length)), out = new Float32Array(n); for (const p of parts) for (let i = 0; i < p.length; i++) out[i] += p[i]; return out; };
const seq = (...parts) => { const n = parts.reduce((s, p) => s + p.length, 0), out = new Float32Array(n); let o = 0; for (const p of parts) { out.set(p, o); o += p.length; } return out; };
const delayed = (p, s) => seq(new Float32Array(secs(s)), p);
function normalize(x, peak = 0.8) { let m = 0; for (const v of x) m = Math.max(m, Math.abs(v)); const k = m ? peak / m : 1; for (let i = 0; i < x.length; i++) x[i] = Math.max(-1, Math.min(1, x[i] * k)); return x; }
function wav(x) {
  const n = x.length, b = Buffer.alloc(44 + n * 2);
  b.write('RIFF', 0); b.writeUInt32LE(36 + n * 2, 4); b.write('WAVE', 8); b.write('fmt ', 12); b.writeUInt32LE(16, 16); b.writeUInt16LE(1, 20); b.writeUInt16LE(1, 22);
  b.writeUInt32LE(SR, 24); b.writeUInt32LE(SR * 2, 28); b.writeUInt16LE(2, 32); b.writeUInt16LE(16, 34); b.write('data', 36); b.writeUInt32LE(n * 2, 40);
  for (let i = 0; i < n; i++) b.writeInt16LE(Math.round(x[i] * 32767), 44 + i * 2);
  return b;
}

// ---- the sounds
const NOTE = (n) => 440 * 2 ** ((n - 69) / 12);   // MIDI note -> Hz
const S = {
  // the coin: B5 for 70 ms, then E6 ringing out (the classic console coin)
  coin: () => seq(tone(0.07, () => NOTE(83), { duty: 0.5, decay: 1 }), tone(0.32, () => NOTE(88), { duty: 0.5, decay: 0.3 })),
  // good gate: two quick rising beeps; ok gate: one short beep
  'beep-good': () => seq(tone(0.08, () => NOTE(81), { duty: 0.3, decay: 0.09 }), tone(0.16, () => NOTE(86), { duty: 0.3, decay: 0.14 })),
  'beep-ok': () => tone(0.12, () => NOTE(79), { duty: 0.3, decay: 0.11 }),
  // the combo: a rising tru-lu-lu (C5 E5 G5 C6), square with a little vibrato
  combo: () => seq(...[72, 76, 79, 84].map((n, i) => tone(i === 3 ? 0.22 : 0.075, () => NOTE(n), { duty: 0.4, decay: i === 3 ? 0.2 : 0.08, vib: 0.01 }))),
  // nitro: a whoosh up: saw sweep 180 -> 1500 Hz with a noise rush, swelling then cut
  nitro: () => mix(tone(0.5, (t) => 180 * (1500 / 180) ** Math.min(1, t / 0.4), { wave: 'saw', amp: 0.7, attack: 0.08, decay: 0.42 }),
    burst(0.5, { lp: (t) => 600 + 5000 * Math.min(1, t / 0.4), hp: 300, amp: 0.8, attack: 0.1, decay: 0.4 })),
  // hits: a boom: sine drop + low noise thump (light short and higher, heavy long and deep)
  'boom-light': () => mix(tone(0.18, (t) => 220 * Math.exp(-t * 14), { wave: 'sine', amp: 1, decay: 0.17 }), burst(0.12, { lp: () => 900, amp: 0.6, decay: 0.1, crush: 2 })),
  'boom-medium': () => mix(tone(0.3, (t) => 170 * Math.exp(-t * 10), { wave: 'sine', amp: 1, decay: 0.28 }), burst(0.2, { lp: () => 700, amp: 0.7, decay: 0.16, crush: 2 })),
  'boom-heavy': () => mix(tone(0.5, (t) => 140 * Math.exp(-t * 7), { wave: 'sine', amp: 1, decay: 0.48 }), burst(0.32, { lp: () => 500, amp: 0.8, decay: 0.28, crush: 3 }), burst(0.06, { lp: () => 3000, amp: 0.5, decay: 0.05 })),
  // smashed things: a short crunch (crushed noise) with the thing's character
  'crunch-c-1': () => mix(burst(0.1, { lp: () => 3500, hp: 400, decay: 0.09, crush: 3 }), tone(0.05, (t) => 900 * Math.exp(-t * 30), { wave: 'tri', amp: 0.5, decay: 0.05 })),
  'crunch-c-2': () => mix(burst(0.09, { lp: () => 4200, hp: 500, decay: 0.08, crush: 2 }), tone(0.05, (t) => 1100 * Math.exp(-t * 30), { wave: 'tri', amp: 0.5, decay: 0.05 })),
  'crunch-b-1': () => mix(burst(0.14, { lp: () => 2500, hp: 200, decay: 0.12, crush: 3 }), tone(0.2, () => 620, { wave: 'tri', amp: 0.45, decay: 0.18, vib: 0.02 })),   // the bin rings
  'crunch-b-2': () => mix(burst(0.13, { lp: () => 2800, hp: 200, decay: 0.11, crush: 3 }), tone(0.18, () => 740, { wave: 'tri', amp: 0.45, decay: 0.16, vib: 0.02 })),
  'crunch-t-1': () => mix(burst(0.16, { lp: () => 1500, hp: 120, decay: 0.14, crush: 4 }), tone(0.08, (t) => 300 * Math.exp(-t * 12), { wave: 'sine', amp: 0.7, decay: 0.08 })),   // the table: low wood
  'crunch-t-2': () => mix(burst(0.18, { lp: () => 1300, hp: 120, decay: 0.16, crush: 4 }), tone(0.08, (t) => 260 * Math.exp(-t * 12), { wave: 'sine', amp: 0.7, decay: 0.08 })),
  'crunch-u-1': () => seq(burst(0.06, { lp: () => 3000, hp: 300, decay: 0.05, crush: 2 }), burst(0.09, { lp: () => 2200, hp: 300, decay: 0.08, crush: 2, amp: 0.8 })),   // the umbrella: two flaps
  'crunch-u-2': () => seq(burst(0.05, { lp: () => 3400, hp: 300, decay: 0.045, crush: 2 }), burst(0.1, { lp: () => 2000, hp: 300, decay: 0.09, crush: 2, amp: 0.8 })),
  // near miss: a whistle (sine 1200 -> 2300 -> 1400 Hz) over a swish of band-passed noise
  whistle: () => mix(tone(0.32, (t) => 1200 + 1100 * Math.sin(Math.PI * Math.min(1, t / 0.32)), { wave: 'sine', amp: 0.8, attack: 0.02, decay: 0.3 }),
    burst(0.3, { lp: (t) => 2500 + 3000 * Math.sin(Math.PI * t / 0.3), hp: 1200, amp: 0.7, attack: 0.05, decay: 0.25 })),
};

await mkdir(OUT, { recursive: true });
const report = [];
for (const [name, make] of Object.entries(S)) {
  seed = 12345 + name.length * 7919;
  const x = normalize(make());
  await writeFile(`${OUT}/${name}.wav`, wav(x));
  report.push(`${name}: ${(x.length / SR).toFixed(2)} s`);
}
console.log(`${report.length} sounds -> ${OUT}/\n  ` + report.join('\n  '));
